create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,owner_id uuid not null references auth.users(id),stripe_customer_id text,plan text not null default 'trial',created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,target_name text not null,place_id text,center_lat double precision not null,center_lng double precision not null,created_at timestamptz not null default now());
create table public.keywords(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,query text not null,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.devices(id uuid primary key default gen_random_uuid(),external_id text unique not null,name text not null,status text not null default 'offline' check(status in('offline','ready','busy','error')),last_seen_at timestamptz,created_at timestamptz not null default now());
create table public.runs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,keyword_id uuid not null references public.keywords(id) on delete cascade,status text not null default 'queued',grid_size int not null,spacing_meters int not null,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.run_points(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.runs(id) on delete cascade,device_id uuid references public.devices(id),row int not null,col int not null,latitude double precision not null,longitude double precision not null,verified_lat double precision,verified_lng double precision,status text not null default 'queued',rank int,matched_name text,screenshot_url text,provider_task_id text,error_message text,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(run_id,row,col));
create index run_points_queue_idx on public.run_points(status,created_at);
create index runs_project_created_idx on public.runs(project_id,created_at desc);
alter table public.organizations enable row level security;alter table public.projects enable row level security;alter table public.keywords enable row level security;alter table public.runs enable row level security;alter table public.run_points enable row level security;alter table public.devices enable row level security;
create policy org_owner_all on public.organizations for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy project_org_access on public.projects for all to authenticated using(exists(select 1 from public.organizations o where o.id=organization_id and o.owner_id=(select auth.uid()))) with check(exists(select 1 from public.organizations o where o.id=organization_id and o.owner_id=(select auth.uid())));
create policy keyword_project_access on public.keywords for all to authenticated using(exists(select 1 from public.projects p join public.organizations o on o.id=p.organization_id where p.id=project_id and o.owner_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organizations o on o.id=p.organization_id where p.id=project_id and o.owner_id=(select auth.uid())));
create policy run_project_access on public.runs for all to authenticated using(exists(select 1 from public.projects p join public.organizations o on o.id=p.organization_id where p.id=project_id and o.owner_id=(select auth.uid()))) with check(exists(select 1 from public.projects p join public.organizations o on o.id=p.organization_id where p.id=project_id and o.owner_id=(select auth.uid())));
create policy point_run_access on public.run_points for select to authenticated using(exists(select 1 from public.runs r join public.projects p on p.id=r.project_id join public.organizations o on o.id=p.organization_id where r.id=run_id and o.owner_id=(select auth.uid())));
revoke all on public.devices from anon,authenticated;
grant select,insert,update,delete on public.organizations,public.projects,public.keywords,public.runs to authenticated;grant select on public.run_points to authenticated;
